graphql.query:
mutation Register($input: RegisterInput!) {
    register(input: $input) {
        message
    token
    user {
    id
    name
    email
    roles {
        key
    }
    createdAt
    updatedAt
    }
    }
}

query Me {
    me {
    id
    name
    email
    roles {
        key
    }
    createdAt
    updatedAt
    }
}

mutation Login($input: LoginInput!) {
    login(input: $input) {
    token
    user {
    id
    name
    email
    roles {
        key
    }
    createdAt
    updatedAt
    }
    }
}

mutation ChangePassword($input: ChangePasswordInput!) {
    changePassword(input: $input) {
    token
    user {
    id
    name
    email
    roles {
        key
    }
    createdAt
    updatedAt
    }
    }
}

query Users($page: Int, $limit: Int) {
    users(page: $page, limit: $limit) {
        data {
    id
    name
    email
    roles {
        key
    }
    createdAt
    updatedAt
        }
        page
        limit
        total
        totalPages
    }
}

mutation CreateExample($input: CreateExampleInput!) {
    createExample(input: $input) {
id
firstName
lastName
createdAt
updatedAt
    }
}

query Examples($page: Int, $limit: Int) {
    examples(page: $page, limit: $limit) {
        data {
id
firstName
lastName
createdAt
updatedAt
        }
        page
        limit
        total
        totalPages
    }
}

query Example($id: ID!) {
    example(id: $id) {
id
firstName
lastName
createdAt
updatedAt
    }
}

mutation UpdateExample($id: ID!, $input: UpdateExampleInput!) {
    updateExample(id: $id, input: $input) {
id
firstName
lastName
createdAt
updatedAt
    }
}

mutation UpdateExample($id: ID!, $input: UpdateExampleInput!) {
    updateExample(id: $id, input: $input) {
        id
    }
}
